body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: transparent;
  color: #111827;
}

.pay-app {
  width: 100%;
  box-sizing: border-box;
  padding: 16px;
  background: #fff;
}

.pay-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
  margin-bottom: 16px;
}

.eyebrow {
  color: #667085;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

h2 {
  margin: 3px 0 0;
  font-size: 22px;
}

.summary {
  display: grid;
  grid-template-columns: repeat(4, 120px);
  gap: 8px;
}

.summary div {
  padding: 10px;
  border-radius: 8px;
  background: #f2f4f7;
  border: 1px solid #d0d5dd;
  text-align: right;
}

.summary span {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 800;
}

.summary strong {
  display: block;
  margin-top: 4px;
  font-size: 17px;
}

.methods {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin-bottom: 14px;
}

.method {
  min-height: 76px;
  border: 1px solid #d0d5dd;
  border-radius: 9px;
  background: #f9fafb;
  cursor: pointer;
  padding: 10px;
  text-align: left;
}

.method.active {
  border-color: #111827;
  background: #111827;
  color: white;
}

.method strong {
  display: block;
  font-size: 14px;
}

.method span {
  display: block;
  margin-top: 4px;
  color: #667085;
  font-size: 11px;
}

.method.active span {
  color: #d1d5db;
}

.entry {
  display: grid;
  grid-template-columns: 1.2fr 140px 1fr 160px;
  gap: 10px;
  align-items: end;
  padding: 12px;
  border: 1px solid #d0d5dd;
  border-radius: 9px;
  background: #fff;
  margin-bottom: 14px;
}

label {
  display: block;
  color: #667085;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 800;
  margin-bottom: 5px;
}

.selected {
  min-height: 40px;
  line-height: 40px;
  border: 1px solid #d0d5dd;
  border-radius: 7px;
  padding: 0 10px;
  font-weight: 800;
  background: #f9fafb;
}

input {
  width: 100%;
  height: 40px;
  border: 1px solid #d0d5dd;
  border-radius: 7px;
  padding: 0 10px;
  box-sizing: border-box;
  font-weight: 700;
}

button {
  height: 40px;
  border: 0;
  border-radius: 7px;
  background: #111827;
  color: white;
  font-weight: 900;
  cursor: pointer;
}

.payments-box {
  border: 1px solid #d0d5dd;
  border-radius: 9px;
  overflow: hidden;
}

.box-title {
  background: #111827;
  color: white;
  padding: 10px 12px;
  font-weight: 900;
}

.payment-row {
  display: grid;
  grid-template-columns: 1fr 110px 1fr 42px;
  gap: 8px;
  align-items: center;
  padding: 9px 12px;
  border-bottom: 1px solid #eaecf0;
  font-size: 13px;
}

.payment-row:last-child {
  border-bottom: 0;
}

.payment-row b {
  text-align: right;
}

.remove {
  height: 30px;
  background: #fee2e2;
  color: #991b1b;
}

.empty {
  padding: 18px;
  color: #667085;
  text-align: center;
}

.actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 14px;
}

.confirm {
  min-width: 190px;
  background: #16a34a;
}

.confirm:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

@media (max-width: 900px) {
  .pay-header {
    display: block;
  }
  .summary {
    grid-template-columns: repeat(2, 1fr);
    margin-top: 12px;
  }
  .methods {
    grid-template-columns: repeat(2, 1fr);
  }
  .entry {
    grid-template-columns: 1fr;
  }
}

