let state = {
  selectedMethod: null,
  payments: []
};
function money(value) {
  return Number(value || 0).toFixed(2);
}
function normalizeMethod(method) {
  return {
    paymentMethodId: method.paymentMethodId || method.id || null,
    code: method.code || method.value || "",
    name: method.name || method.label || method.code || "",
    methodGroup: method.methodGroup || method.method_group || "",
    isCash: Number(method.isCash || method.is_cash || 0) === 1,
    requiresReference: Number(method.requiresReference || method.requires_reference || 0) === 1,
    requiresCardType: Number(method.requiresCardType || method.requires_card_type || 0) === 1
  };
}
function totals(model) {
  const totalDue = Number(model.totalDue || 0);
  const paid = state.payments.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  const remaining = Math.max(totalDue - paid, 0);
  const change = Math.max(paid - totalDue, 0);
  return {
    totalDue,
    paid,
    remaining,
    change
  };
}
function sync(model) {
  const t = totals(model);
  appsmith.updateModel({
    payments: state.payments,
    paid: Number(t.paid.toFixed(2)),
    remaining: Number(t.remaining.toFixed(2)),
    change: Number(t.change.toFixed(2))
  });
  appsmith.triggerEvent("onPaymentChange");
}
function render(model = {}) {
  const methods = (model.methods || []).map(normalizeMethod);
  state.payments = Array.isArray(model.payments) ? model.payments : [];
  const t = totals(model);
  const currency = model.currency || "EUR";
  document.getElementById("totalDue").innerText = `${money(t.totalDue)} ${currency}`;
  document.getElementById("paid").innerText = `${money(t.paid)} ${currency}`;
  document.getElementById("remaining").innerText = `${money(t.remaining)} ${currency}`;
  document.getElementById("change").innerText = `${money(t.change)} ${currency}`;
  document.getElementById("methods").innerHTML = methods.map(method => `
    <button class="method ${state.selectedMethod?.code === method.code ? "active" : ""}" data-code="${method.code}">
      <strong>${method.name}</strong>
      <span>${method.methodGroup}</span>
    </button>
  `).join("");
  document.querySelectorAll(".method").forEach(button => {
    button.onclick = () => {
      state.selectedMethod = methods.find(method => method.code === button.dataset.code) || null;
      const nextAmount = totals(model).remaining || totals(model).totalDue;
      document.getElementById("selectedMethod").innerText = state.selectedMethod?.name || "-";
      document.getElementById("amountInput").value = money(nextAmount);
      document.getElementById("referenceInput").value = "";
      render(model);
    };
  });
  document.getElementById("payments").innerHTML = state.payments.length ? state.payments.map((row, index) => `
      <div class="payment-row">
        <span>${row.name || row.code}</span>
        <b>${money(row.amount)} ${currency}</b>
        <span>${row.referenceNumber || ""}</span>
        <button class="remove" data-index="${index}">x</button>
      </div>
    `).join("") : `<div class="empty">No payments added.</div>`;
  document.querySelectorAll(".remove").forEach(button => {
    button.onclick = () => {
      const index = Number(button.dataset.index);
      state.payments.splice(index, 1);
      sync(model);
      render({
        ...model,
        payments: state.payments
      });
    };
  });
  document.getElementById("addBtn").onclick = () => {
    if (!state.selectedMethod) {
      alert("Select payment method first.");
      return;
    }
    const amount = Number(document.getElementById("amountInput").value || 0);
    const referenceNumber = String(document.getElementById("referenceInput").value || "").trim();
    if (amount <= 0) {
      alert("Enter payment amount.");
      return;
    }
    if (state.selectedMethod.requiresReference && !referenceNumber) {
      alert("Reference is required for this payment method.");
      return;
    }
    state.payments.push({
      paymentMethodId: state.selectedMethod.paymentMethodId,
      code: state.selectedMethod.code,
      name: state.selectedMethod.name,
      methodGroup: state.selectedMethod.methodGroup,
      isCash: state.selectedMethod.isCash,
      requiresReference: state.selectedMethod.requiresReference,
      amount,
      referenceNumber
    });
    sync(model);
    render({
      ...model,
      payments: state.payments
    });
  };
  document.getElementById("confirmBtn").disabled = t.paid < t.totalDue;
  document.getElementById("confirmBtn").onclick = () => {
    if (totals(model).paid < totals(model).totalDue) {
      alert("Payment amount is lower than total.");
      return;
    }
    appsmith.triggerEvent("onConfirmPayment");
  };
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

